-- 强一致关系与状态约束；多态目标由应用层按类型检查，不能伪造 FK。
ALTER TABLE app_user ADD CONSTRAINT fk_app_user_organization FOREIGN KEY(organization_id) REFERENCES organization(id);
ALTER TABLE article_version ADD UNIQUE KEY uk_article_version_owner(article_id,id);
ALTER TABLE article_version ADD CONSTRAINT fk_version_article FOREIGN KEY(article_id) REFERENCES article(id);
ALTER TABLE article ADD CONSTRAINT fk_article_current_version FOREIGN KEY(id,current_version_id) REFERENCES article_version(article_id,id);
ALTER TABLE article ADD CONSTRAINT fk_article_latest_version FOREIGN KEY(id,latest_version_id) REFERENCES article_version(article_id,id);
ALTER TABLE article_category_rel ADD CONSTRAINT fk_ac_article FOREIGN KEY(article_id) REFERENCES article(id);
ALTER TABLE article_category_rel ADD CONSTRAINT fk_ac_category FOREIGN KEY(category_id) REFERENCES content_category(id);
ALTER TABLE article_organization_rel ADD CONSTRAINT fk_ao_article FOREIGN KEY(article_id) REFERENCES article(id);
ALTER TABLE article_organization_rel ADD CONSTRAINT fk_ao_organization FOREIGN KEY(organization_id) REFERENCES organization(id);
ALTER TABLE article_keyword_rel ADD CONSTRAINT fk_ak_article FOREIGN KEY(article_id) REFERENCES article(id);
ALTER TABLE article_keyword_rel ADD CONSTRAINT fk_ak_keyword FOREIGN KEY(keyword_id) REFERENCES keyword(id);
ALTER TABLE article_review ADD CONSTRAINT fk_review_version FOREIGN KEY(article_id,version_id) REFERENCES article_version(article_id,id);
ALTER TABLE article_replacement ADD CONSTRAINT fk_replacement_old FOREIGN KEY(old_article_id) REFERENCES article(id);
ALTER TABLE article_replacement ADD CONSTRAINT fk_replacement_new FOREIGN KEY(new_article_id) REFERENCES article(id);
ALTER TABLE article_replacement ADD CONSTRAINT chk_replacement_self CHECK(old_article_id<>new_article_id);
ALTER TABLE user_follow ADD CONSTRAINT fk_follow_user FOREIGN KEY(user_id) REFERENCES app_user(id);
ALTER TABLE user_follow ADD CONSTRAINT chk_follow_type CHECK(target_type IN ('KEYWORD','ARTICLE'));
ALTER TABLE user_favorite ADD CONSTRAINT fk_favorite_user FOREIGN KEY(user_id) REFERENCES app_user(id);
ALTER TABLE user_favorite ADD CONSTRAINT fk_favorite_article FOREIGN KEY(article_id) REFERENCES article(id);
ALTER TABLE user_browse_history ADD CONSTRAINT fk_browse_user FOREIGN KEY(user_id) REFERENCES app_user(id);
ALTER TABLE user_browse_history ADD CONSTRAINT fk_browse_article FOREIGN KEY(article_id) REFERENCES article(id);
ALTER TABLE user_read_state ADD CONSTRAINT fk_read_user FOREIGN KEY(user_id) REFERENCES app_user(id);
ALTER TABLE user_read_state ADD CONSTRAINT fk_read_article FOREIGN KEY(article_id) REFERENCES article(id);
ALTER TABLE user_report ADD CONSTRAINT fk_report_user FOREIGN KEY(user_id) REFERENCES app_user(id);
ALTER TABLE user_report ADD CONSTRAINT fk_report_article FOREIGN KEY(article_id) REFERENCES article(id);
ALTER TABLE app_user_identity ADD CONSTRAINT fk_identity_user FOREIGN KEY(user_id) REFERENCES app_user(id);
ALTER TABLE feedback ADD CONSTRAINT fk_feedback_user FOREIGN KEY(user_id) REFERENCES app_user(id);
ALTER TABLE user_exposure ADD CONSTRAINT fk_exposure_user FOREIGN KEY(user_id) REFERENCES app_user(id);
ALTER TABLE user_exposure ADD CONSTRAINT fk_exposure_article FOREIGN KEY(article_id) REFERENCES article(id);
ALTER TABLE user_exposure ADD CONSTRAINT chk_exposure_count CHECK(visible_count>=0);
ALTER TABLE home_recommendation ADD CONSTRAINT fk_home_article FOREIGN KEY(article_id) REFERENCES article(id);
ALTER TABLE notification_rule ADD CONSTRAINT fk_notification_rule_user FOREIGN KEY(user_id) REFERENCES app_user(id);
ALTER TABLE notification_delivery ADD CONSTRAINT fk_delivery_user FOREIGN KEY(user_id) REFERENCES app_user(id);
ALTER TABLE notification_delivery ADD CONSTRAINT fk_delivery_article FOREIGN KEY(article_id) REFERENCES article(id);
